// Body › Visualize shows the patients as a table (Postman Visualizer)
const template = `
<h3>{{total}} patients</h3>
<table>
  <tr><th>ID</th><th>Name</th><th>Species</th><th>Owner</th></tr>
  {{#each items}}
    <tr><td>{{id}}</td><td>{{name}}</td><td>{{species}}</td><td>{{ownerId}}</td></tr>
  {{/each}}
</table>`;
pm.visualizer.set(template, pm.response.json());
